<template><div class="demo-widget universal-demo-widget" :style="style"><span class="widget-kicker">{{ kicker }}</span><b>{{ title }}</b><p>{{ subtitle }}</p><div v-if="widget.settings.progress!==undefined" class="progress-track"><i :style="{width:`${widget.settings.progress}%`}"></i></div></div></template>
<script setup>import{computed,watch}from'vue';import{useWidgetEvents}from'../../widgetHelpers.js';const props=defineProps({widget:{type:Object,required:true},runtimeMode:{type:String,default:'editor-preview'},runtimeConfig:{type:Object,default:null}});const alertTypes=new Set(['subscription-alert','raid-alert']);const event=useWidgetEvents(props.widget,props.runtimeMode==='browser-source'&&alertTypes.has(props.widget.type)?null:{actor:null,payload:{}});const style=computed(()=>({background:props.widget.settings.background,opacity:props.widget.settings.opacity,borderRadius:`${props.widget.settings.cornerRadius}px`,color:props.widget.settings.color||'#fff'}));const kind=computed(()=>props.widget.type==='raid-alert'?'raid':'subscription');const config=computed(()=>props.runtimeConfig?.alerts?.[kind.value]||null);const kicker=computed(()=>props.runtimeMode==='browser-source'&&alertTypes.has(props.widget.type)?(props.widget.type==='raid-alert'?'Incoming raid':'New subscriber'):props.widget.settings.kicker);const title=computed(()=>{if(!event.value||props.runtimeMode!=='browser-source')return props.widget.settings.title;const actor=event.value.actor?.displayName||'A community member',payload=event.value.payload||{},fallback=props.widget.type==='raid-alert'?'{user} brought {viewers} viewers':'{user} subscribed!';return String(config.value?.template||fallback).replaceAll('{user}',actor).replaceAll('{viewers}',String(payload.viewers||0))});const subtitle=computed(()=>props.runtimeMode==='browser-source'&&alertTypes.has(props.widget.type)?'':props.widget.settings.subtitle);watch(event,()=>{if(props.runtimeMode!=='browser-source'||!config.value?.soundUrl)return;const audio=new Audio(config.value.soundUrl);audio.volume=Number(config.value.volume??1);void audio.play().catch(()=>{})})</script>
